    h,w=len(grid),len(grid[0])
    cnt={}
    for row in grid:
        for x in row: cnt[x]=cnt.get(x,0)+1
    bg=max(cnt,key=cnt.get)
    pos={}
    for r in range(h):
        for c in range(w):
            x=grid[r][c]
            if x!=bg: pos.setdefault(x,[]).append((r,c))
    mark=None
    for x,ps in pos.items():
        if len(ps)==4:
            rs=[p[0] for p in ps]; cs=[p[1] for p in ps]
            a,b=min(rs),max(rs); l,d=min(cs),max(cs)
            if set(ps)=={(a,l),(a,d),(b,l),(b,d)}:
                mark=(x,a,b,l,d); break
    if mark is None: return [row[:] for row in grid]
    mc,a,b,l,d=mark; pts=[]
    corners={(a,l),(a,d),(b,l),(b,d)}
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=bg and (r,c) not in corners: pts.append((r,c,grid[r][c]))
    if not pts: return [[bg]*w for _ in range(h)]
    r0=min(p[0] for p in pts); r1=max(p[0] for p in pts); c0=min(p[1] for p in pts); c1=max(p[1] for p in pts)
    ih,iw=b-a-1,d-l-1; ph,pw=r1-r0+1,c1-c0+1
    nr=max(a+1,min(r0,b-ph)); nc=max(l+1,min(c0,d-pw))
    out=[[bg]*w for _ in range(h)]
    for r,c in corners: out[r][c]=mc
